  var year = int.parse(inputString.substring(0, 4));
  if (year == -1) {
    return DateTime(dateTime.year + 1, dateTime.month, dateTime.day);
  } else if (year > Int32.maxValue || year < Int32.minValue) {
    throw ArgumentError('Year out of range');
  }
  var month = int.parse(inputString.substring(5, 7));
  if (month == -1) {
    return DateTime(year, dateTime.month + 1, dateTime.day);
  } else if (month > 12) {
    throw ArgumentError('Month out of range');
  }
  var day = int.parse(inputString.substring(8, 10));
  if (day == -1) {
    return DateTime(year, month, dateTime.day + 1);
  } else if (day > DateTime.daysPerMonth(year, month)) {
    throw ArgumentError('Day out of range for specified month and year');
  }
  return DateTime(year, month, day);
}

