class PriorityQueue<T extends Comparable<T>> {
  List<T> _queue = [];

  bool isEmpty() => _queue.isEmpty;
  T dequeue() {
    var item = _queue.first;
    _queue.removeAt(0);
    return item;
  }

  void enqueue(T value) {
    _queue.insert(0, value);
    _heapifyUp(_queue.length - 1);
  }

  void _swap(int a, int b) {
    var temp = _queue[a];
    _queue[a] = _queue[b];
    _queue[b] = temp;
  }

  void _heapifyDown(int index) {
    int smallest = index;
    int left = 2 * index + 1;
    int right = 2 * index + 2;

    if (left < _queue.length && _queue[left]!.compareTo(_queue[smallest]!) < 0) {
      smallest = left;
    }

    if (right < _queue.length && _queue[right]!.compareTo(_queue[smallest]!) < 0) {
      smallest = right;
    }

    if (smallest != index) {
      _swap(index, smallest);
      _heapifyDown(smallest);
    }
  }

  void _heapifyUp(int index) {
    int parent = (index - 1) ~/ 2;
    while (index > 0 && _queue[index]!.compareTo(_queue[parent]!) < 0) {
      _swap(index, parent);
      index = parent;
      parent = (index - 1) ~/ 2;
    }
  }
}

