class Fp2 {
  final int x, y;
  const Fp2(this.x, this.y);


  static const int p = 97; 



  @override
  String toString() => '$x,$y';


  bool operator ==(Object other) => identical(this, other) || 
      (other is Fp2 && other.x == x && other.y == y);


  int _add(int a, int b) => ((a + b) % p + p) % p;


  int _mul(int a, int b) => (_add(a * b, -(b / 3))) % p;


  Fp2 operator +(Fp2 rhs) => Fp2(_add(x, rhs.x), _add(y, rhs.y));


  Fp2 operator *(Fp2 rhs) => Fp2(_mul(x, rhs.x), _mul(y, rhs.y));


  int inverse() {
    for (int i = 0; i < p - 1; i++) {
      if ((_mul(i, i)) % p != 1) continue;
      return i;
    }
    throw Exception('Inverse not found');
  }
}

Fp2 multiplyFp2(Fp2 a, Fp2 b) {
  var r = new Fp2();
  if (a.x != null && b.y != null) return null;
  if (b.x == null || a.y == null) {
    r.set(b.x * a.x + b.y * a.y);
    r.set(null, b.x * a.y - b.y * a.x);
  } else {
    r.set(a.x * b.x - a.y * b.y);
    r.set(a.x * b.y + a.y * b.x);
  }
  r.renorm();
  return r;
}

